package cue

import (
	_ \"embed\"
	\"errors\"
	\"fmt\"

	\"cuelang.org/go/cue\"
	\"cuelang.org/go/cue/cuecontext\"
	cueerrors \"cuelang.org/go/cue/errors\"
	\"cuelang.org/go/encoding/yaml\"
	yamlv3 \"gopkg.in/yaml.v3\"
)

var (
	//go:embed flipt.cue
	cueFile []byte
	ErrValidationFailed = errors.New(\"validation failed\")
)

// Location identifies the source of a validation error.
type Location struct {
	File string "'`json:"file,omitempty"`
	Line int `json:"line"`
	Column int `json:"column"`
}

// Error is one validation issue and its source location.
type Error struct {
	Message string `json:"message"`
	Location Location `json:"location"`
}

func (e Error) Error() string {
	return fmt.Sprintf("%s (%s %d:%d)", e.Message, e.Location.File, e.Location.Line, e.Location.Column)
}

type validationErrors struct { issues []error }

func (e validationErrors) Error() string { return ErrValidationFailed.Error() }
func (e validationErrors) Unwrap() []error { return e.issues }
func (e validationErrors) Is(target error) bool { return target == ErrValidationFailed }

// Unwrap returns the individual errors in a multi-error value.
func Unwrap(err error) ([]error, bool) {
	var multi interface { Unwrap() []error }
	if errors.As(err, &multi) {
		return multi.Unwrap(), true
	}
	return nil, false
}

type FeaturesValidator struct {
	cue *cue.Context
	v cue.Value
}

func NewFeaturesValidator() (*FeaturesValidator, error) {
	cctx := cuecontext.New()
	v := cctx.CompileBytes(cueFile)
	if v.Err() != nil { return nil, v.Err() }
	return &FeaturesValidator{cue: cctx, v: v}, nil
}

// Validate checks a YAML state file against the schema and its local references.
func (v FeaturesValidator) Validate(file string, b []byte) error {
	f, err := yaml.Extract(file, b)
	if err != nil { return err }
	yv := v.cue.BuildFile(f)
	if err := yv.Err(); err != nil { return err }

	var issues []error
	for _, e := range cueerrors.Errors(v.v.Unify(yv).Validate(cue.All(), cue.Concrete(true))) {
		issue := Error{Message: e.Error(), Location: Location{File: file}}
		if pos := cueerrors.Positions(e); len(pos) > 0 {
			p := pos[len(pos)-1]
			issue.Location.Line, issue.Location.Column = p.Line(), p.Column()
		}
		issues = append(issues, issue)
	}

	var root yamlv3.Node
	if err := yamlv3.Unmarshal(b, &root); err != nil { return err }
	if len(root.Content) > 0 { issues = append(issues, referenceErrors(file, root.Content[0])...) }
	if len(issues) > 0 { return validationErrors{issues: issues} }
	return nil
}

func field(node *yamlv3.Node, name string) *yamlv3.Node {
	if node == nil || node.Kind != yamlv3.MappingNode { return nil }
	for i := 0; i+1 < len(node.Content); i += 2 {
		if node.Content[i].Value == name { return node.Content[i+1] }
	}
	return nil
}

func items(node *yamlv3.Node) []*yamlv3.Node {
	if node == nil || node.Kind != yamlv3.SequenceNode { return nil }
	return node.Content
}

func referenceErrors(file string, doc *yamlv3.Node) []error {
	namespace := "default"
	if n := field(doc, "namespace"); n != nil && n.Value != "" { namespace = n.Value }
	segments := make(map[string]bool)
	for _, segment := range items(field(doc, "segments")) {
		if key := field(segment, "key"); key != nil { segments[key.Value] = true }
	}
	var issues []error
	for _, flag := range items(field(doc, "flags")) {
		flagKey := ""
		if key := field(flag, "key"); key != nil { flagKey = key.Value }
		variants := make(map[string]bool)
		for _, variant := range items(field(flag, "variants")) {
			if key := field(variant, "key"); key != nil { variants[key.Value] = true }
		}
		for i, rule := range items(field(flag, "rules")) {
			prefix := fmt.Sprintf("flag %s/%s rule %d references unknown", namespace, flagKey, i+1)
			checkSegment := func(key *yamlv3.Node) {
				if key != nil && key.Kind == yamlv3.ScalarNode && !segments[key.Value] {
					issues = append(issues, Error{Message: fmt.Sprintf("%s segment %q", prefix, key.Value), Location: Location{File: file, Line: key.Line, Column: key.Column}})
				}
			}
			segment := field(rule, "segment")
			if segment != nil && segment.Kind == yamlv3.ScalarNode { checkSegment(segment) }
			for _, key := range items(field(segment, "keys")) { checkSegment(key) }
			for _, dist := range items(field(rule, "distributions")) {
				key := field(dist, "variant")
				if key != nil && key.Kind == yamlv3.ScalarNode && !variants[key.Value] {
					issues = append(issues, Error{Message: fmt.Sprintf("%s variant %q", prefix, key.Value), Location: Location{File: file, Line: key.Line, Column: key.Column}})
				}
			}
		}
	}
	return issues
