)

type importCommand struct {
	dropBeforeImport bool
	importStdin      bool
	address          string
	token            string
	namespace        string
	createNamespace  bool
}

func newImportCommand() *cobra.Command {
	importCmd := &importCommand{}

	cmd := &cobra.Command{
		Use:   "import",
		Short: "Import flags/segments/rules from file",
		RunE:  importCmd.run,
	}

	cmd.Flags().BoolVar(
		&importCmd.dropBeforeImport,
		"drop",
		false,
		"drop database before import",
	)

	cmd.Flags().BoolVar(
		&importCmd.importStdin,
		"stdin",
		false,
		"import from STDIN",
	)

	cmd.Flags().StringVarP(
		&importCmd.address,
		"address", "a",
		"",
		"address of remote Flipt instance to import into (defaults to direct DB import if not supplied)",
	)

	cmd.Flags().StringVarP(
		&importCmd.token,
		"token", "t",
		"",
		"client token used to authenticate access to remote Flipt instance when importing.",
	)

	cmd.Flags().StringVarP(
		&importCmd.namespace,
		"namespace", "n",
		flipt.DefaultNamespace,
		"destination namespace for imported resources.",
	)

	cmd.Flags().BoolVar(
		&importCmd.createNamespace,
		"create-namespace",
		false,
		"create the namespace if it does not exist.",
	)

	return cmd
}

func (c *importCommand) run(cmd *cobra.Command, args []string) error {
	var (
		in         io.Reader = os.Stdin
		sourceName           = "stdin"
		logger               = zap.Must(zap.NewDevelopment())
	)

	if !c.importStdin {
		if len(args) < 1 {
			return errors.New("import filename required")
		}

		importFilename := args[0]
		if importFilename == "" {
			return errors.New("import filename required")
		}

		f := filepath.Clean(importFilename)

		logger.Debug("importing", zap.String("source_path", f))

		fi, err := os.Open(f)
		if err != nil {
			return fmt.Errorf("opening import file: %w", err)
		}

		defer fi.Close()

		in = fi
		sourceName = f
	}

	// Validate the complete input before any database operation can mutate state.
	contents, err := io.ReadAll(in)
	if err != nil {
		fmt.Println(err)
		os.Exit(1)
	}

	for _, arg := range args {
		f, err := os.ReadFile(arg)
		if err != nil {
			fmt.Println(err)
			os.Exit(1)
		}

		err = validator.Validate(arg, f)
		issues, ok := cue.Unwrap(err)
		if err != nil && !ok {
			fmt.Println(err)
			os.Exit(1)
		}

		if len(issues) > 0 {
			if v.format == jsonFormat {
				if err := json.NewEncoder(os.Stdout).Encode(struct {
					Errors []error `json:"errors"`
				}{issues}); err != nil {
					fmt.Println(err)
					os.Exit(1)
				}
				os.Exit(v.issueExitCode)
				return
			}

			fmt.Println("Validation failed!")

			for _, issue := range issues {
				e := issue.(cue.Error)
				fmt.Printf(
					`
- Message  : %s
  File     : %s
  Line     : %d
  Column   : %d
`, e.Message, e.Location.File, e.Location.Line, e.Location.Column)
			}

			os.Exit(v.issueExitCode)
		}
	}
}

